// =====================================================================================
//  IDOLVERSE48: Select Bloom! — General Election (総選挙)
//  · S.ge = {seq, cur, list:[election]} — one election record per edition, kept forever.
//  · Flow: setup → producing (GE single in production) → voting (2 calendar months from the
//    GE single's release day) → closed (final results sealed) → scheduled (weekend ceremony)
//    → ceremony (step by step, resumable) → done (archive). Finalised data is never recomputed.
//  · Tokens come only from the GE single's confirmed CD sales (release-day sales + one daily
//    sales record per voting day, each day processed once). Fans in the existing aggregate
//    fanbase (S.fb segments: Kami Oshi / Oshi patterns, loyalty, engagement, spending) cast
//    them; Votes cast + Unused tokens = Tokens generated, always.
//  · Ceremony reactions go through the existing wellness system (Mood, Mental/Physical
//    Health with its mandatory leave, Passion, Loyalty, member history).
//  · Final ranking groups become locked lineups of the next single (main song + couplings).
// =====================================================================================
const GE_EV={...EV.election};delete EV.election; // the old one-shot "General Election" event is replaced by this system
const GE_OUT=[2,350],GE_MAXG=1+CFG.maxTypes*(CFG.maxPerType-1),GE_MAXP=100;
const GE_CAPE={1:{n:'Red Royal Cape & Crown',c:'#d0152f',d:'#7a0618',l:'#ff5b6e',crown:1},2:{n:'Pink Cape',c:'#f27aa9',d:'#b8406e',l:'#ffb4cf'},3:{n:'Light Blue Cape',c:'#79c4ee',d:'#3a86b8',l:'#c4e8ff'}};
const GE_VEN=[['tokyo','Bloom Theater',800,.6],['tokyo','Starlight Hall',3000,1],['kanagawa','Grand Arena',12000,2.4],['aichi','Star Dome',30000,4.5],['osaka','Star Dome',36000,5],['fukuoka','Star Dome',38000,5.2],['tokyo','Festival Stadium',50000,7]].map(([r,t,cap,f],i)=>{const L=RSL[r];return{id:'v'+i,n:`${L?L.city:'Tokyo'} ${t}`,city:L?L.n:'Tokyo',cap,cost:Math.round(GE_EV.cost*f/1000)*1000,f}});
const GE_ST={setup:'Preparing',producing:'Election single in production',voting:'Voting in progress',closed:'Voting closed · results sealed',scheduled:'Ceremony scheduled',ceremony:'Ceremony day',done:'Completed'};
const geRn=n=>ordN(n)+' Place';

// ---- state --------------------------------------------------------------------------------------
function geS(){let G=S.ge;if(!G||typeof G!='object')G=S.ge={seq:0,cur:null,list:[]};G.list=Array.isArray(G.list)?G.list:[];G.seq=+G.seq||0;return G}
const geGet=id=>geS().list.find(e=>e.id==id)||null,geCur=()=>{const G=geS();return geGet(G.cur)};
const geActive=()=>{const e=geCur();return e&&e.st!='done'?e:null};
const geEditable=e=>e&&(e.st=='setup'||e.st=='producing');
const geRanges=e=>{let a=1;return e.groups.map(g=>{const r=[a,a+g.size-1];a+=g.size;return r})};
const geTotal=e=>e.groups.reduce((a,g)=>a+(+g.size||0),0);
const geGroupOf=(e,rank)=>{const R=geRanges(e);return R.findIndex(([a,b])=>rank>=a&&rank<=b)};
function geNew(){const G=geS();if(geActive())return toast('Finish the current General Election first.','err');const n=G.list.length+1;
 const e={id:'ge'+(++G.seq),ed:n,name:`${ordN(n)} General Election`,year:dt().getFullYear(),groups:[{name:'Senbatsu',size:16},{name:'Under Girls',size:16}],parts:[],st:'setup',created:S.day,v:1};
 G.list.push(e);G.cur=e.id;ui.getab='setup';toast(`${e.name} created. Configure it, then produce the General Election Single.`);render()}
function geErr(e){const r=[];if(!e)return['No election.'];if(!String(e.name||'').trim())r.push('Enter an election name.');if(!(+e.year>0))r.push('Enter the election year.');
 if(!e.groups.length)r.push('Create at least one ranking group.');if(e.groups.length>GE_MAXG)r.push(`At most ${GE_MAXG} ranking groups (one main song and ${GE_MAXG-1} coupling songs per single).`);
 e.groups.forEach((g,i)=>{if(!String(g.name||'').trim())r.push(`Ranking group ${i+1} needs a name.`);if(!Number.isInteger(+g.size)||+g.size<1)r.push(`${g.name||'Group '+(i+1)} needs at least 1 ranking position.`);if(+g.size>CFG.maxSen)r.push(`${g.name||'Group '+(i+1)}: at most ${CFG.maxSen} members (largest Senbatsu formation).`)});
 const nm=e.groups.map(g=>String(g.name||'').trim().toLowerCase());if(nm.some((x,i)=>x&&nm.indexOf(x)!=i))r.push('Ranking group names must be different.');
 if(geTotal(e)>GE_MAXP)r.push(`At most ${GE_MAXP} ranked positions in total (now ${geTotal(e)}).`);
 const P=e.parts.filter(id=>{const m=get(id);return m&&m.status!='graduated'});if(!P.length)r.push('Register at least one participant.');if(P.length!=e.parts.length)r.push('Some registered members have left; update the participant list.');return r}
const geLockMsg=()=>toast('The ranking structure and participants are locked once voting has started.','err');
function geSet(k,v){const e=geActive();if(!geEditable(e))return geLockMsg();if(k=='name')e.name=String(v).replace(/[<>]/g,'').slice(0,60);if(k=='year')e.year=Math.max(1,Math.min(9999,Math.round(+v)||e.year));if(k=='ed')e.ed=Math.max(1,Math.min(999,Math.round(+v)||e.ed));render()}
function geGrp(i,k,v){const e=geActive();if(!geEditable(e))return geLockMsg();const g=e.groups[i];if(!g)return;if(k=='name')g.name=String(v).replace(/[<>]/g,'').slice(0,30);if(k=='size'){const n=Math.round(+v);if(!(n>=1))return toast('Each ranking group needs at least 1 position.','err'),render();if(n>CFG.maxSen)return toast(`At most ${CFG.maxSen} positions per group.`,'err'),render();if(geTotal(e)-g.size+n>GE_MAXP)return toast(`At most ${GE_MAXP} ranked positions in total.`,'err'),render();g.size=n}render()}
function geGrpAdd(){const e=geActive();if(!geEditable(e))return geLockMsg();if(e.groups.length>=GE_MAXG)return toast(`At most ${GE_MAXG} ranking groups.`,'err');const left=GE_MAXP-geTotal(e);if(left<1)return toast(`All ${GE_MAXP} positions are used.`,'err');const N=['Senbatsu','Under Girls','Next Girls','Future Girls','Upcoming Girls','Theater Girls','Rising Girls','Dream Girls','Bloom Girls'];const nm=N.find(n=>!e.groups.some(g=>g.name==n))||'Group '+(e.groups.length+1);e.groups.push({name:nm,size:Math.min(16,left)});render()}
function geGrpDel(i){const e=geActive();if(!geEditable(e))return geLockMsg();if(e.groups.length<=1)return toast('An election needs at least one ranking group.','err');e.groups.splice(i,1);render()}
function geGrpMv(i,d){const e=geActive();if(!geEditable(e))return geLockMsg();const j=i+d;if(j<0||j>=e.groups.length)return;[e.groups[i],e.groups[j]]=[e.groups[j],e.groups[i]];render()}
function geTog(id){const e=geActive();if(!geEditable(e))return geLockMsg();const m=get(id);if(!m||m.status=='graduated')return toast('Graduated members cannot take part.','err');const i=e.parts.indexOf(id);if(i>=0)e.parts.splice(i,1);else e.parts.push(id);render()}
function geAll(on){const e=geActive();if(!geEditable(e))return geLockMsg();const f=ui.gepf||'all';e.parts=on?[...new Set([...e.parts,...S.members.filter(m=>m.status!='graduated'&&geMatch(m,f)).map(m=>m.id)])]:e.parts.filter(id=>!geMatch(get(id)||{},f));render()}
const geMatch=(m,f)=>f=='all'||(f=='act'?isAct(m)&&m.tid:f=='tr'?m.status=='trainee':m.group==+f);
function geLink(){const e=geActive();if(!e||e.st!='setup')return toast('This election already has its single.','err');goView('music');const p=S.pj;if(!p||p.status!='draft')return toast('Finish the single currently in production first.','err');if(p.geNext)return toast('This single carries the previous election\'s locked lineups. Release it first.','err');p.ge=e.id;toast('This single is now the General Election Single. Produce it as usual; its CD sales become voting tokens.');render()}
function geUnlink(){const p=S.pj;if(!p||p.status!='draft'||!p.ge)return;delete p.ge;toast('The single is no longer the General Election Single.');render()}
const geSingleOf=e=>e&&e.rid?S.singles.find(x=>x.rid==e.rid):null;
// voting period: release day .. the day before the same date two calendar months later (Jan 1 → Feb 28)
function geEnd(d){const a=dayDate(d),t=new Date(a.getFullYear(),a.getMonth()+2,1),last=new Date(t.getFullYear(),t.getMonth()+1,0).getDate();t.setDate(Math.min(a.getDate(),last));return dateDay(t)-1}
const geIsWE=d=>{const w=dayDate(d).getDay();return w==0||w==6};

// ---- voting simulation (aggregate fanbase) ------------------------------------------------------
const geRandN=()=>{let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)};
const geLive=e=>e.parts.filter(id=>{const m=get(id);return m&&m.status!='graduated'&&!(e.wd||[]).includes(id)});
function geWeights(e,x){const P=geLive(e),W={},PS=new Set(P);P.forEach(id=>W[id]=0);let G=0;const BUY={casual:.02,dedicated:.08,oshi:.12,hardcore:.3,collector:.25};
 ((S.fb&&S.fb.segs)||[]).forEach(s=>{if(!s.n)return;const b=s.n*(BUY[s.ft]||.05)*(.4+(s.sp||40)/100)*(.5+(s.eng||50)/100)*(.7+(s.loy||40)/200);const ks=s.k&&PS.has(s.k)?((FB_PAT[s.pat]||[.75])[0]):0;if(ks)W[s.k]+=b*ks;const rem=b*(1-ks);let os=0;for(const j in s.o)if(PS.has(+j))os+=s.o[j];if(os>0){for(const j in s.o)if(PS.has(+j))W[+j]+=rem*s.o[j]/os}else G+=rem});
 const fz=P.reduce((a,id)=>a+Math.pow(Math.max(1,get(id).fans),.8),0)||1;if(!S.fb||!S.fb.segs||!S.fb.segs.length)G+=Math.max(100,S.fans*.1);
 const mx=x&&S.songs[x.mainId],pos=new Map(((mx&&mx.fm&&mx.fm.sl)||[]).filter(s=>s.m).map(s=>[s.m,s]));
 P.forEach(id=>{const m=get(id),r=srOf(m),w=wlOf(m);W[id]+=G*Math.pow(Math.max(1,m.fans),.8)/fz;const sl=pos.get(id);
  const img=1+((m.traits||[]).some(t=>t=='Cute'||t=='Energetic'||t=='Funny')?.05:0)+(m.pers=='Genki'?.03:0),hist=Math.min(1.25,1+r.cen*.03+r.sel*.008),expo=sl?(sl.c?1.15:sl.r==0?1.08:1.03):1;
  const sg=e.surge&&e.surge[id]&&e.surge[id].until>=S.day?e.surge[id].f:1,cond=w.leave?.9:1;
  W[id]*=(.75+m.pop/200)*(1+m.buzz/250)*img*hist*expo*((e.heat&&e.heat[id])||1)*sg*cond*Math.exp(geRandN()*.12)});return W}
function geAlloc(e,W,V){const ids=Object.keys(W).map(Number),tot=ids.reduce((a,i)=>a+W[i],0);if(!V||!ids.length)return 0;let used=0;const fr=[];
 ids.forEach(id=>{const q=tot>0?V*W[id]/tot:V/ids.length,f=Math.floor(q);if(f>0){e.votes[id]=(e.votes[id]||0)+f;e.last[id]=++e.ts;used+=f}fr.push([id,q-f])});
 let left=V-used;while(left>0){let t=fr.reduce((a,z)=>a+z[1],0),k=Math.random()*(t||1),pick=fr[0][0];for(const[id,w]of fr){k-=w;if(k<=0){pick=id;break}}if(t<=0)pick=fr[Math.floor(Math.random()*fr.length)][0];e.votes[pick]=(e.votes[pick]||0)+1;e.last[pick]=++e.ts;left--}return V}
const geSorted=e=>geLive(e).map(id=>({id,v:e.votes[id]||0,t:e.last[id]||0})).sort((a,b)=>b.v-a.v||a.t-b.t||a.id-b.id);
function geDemand(e,x){const t=S.day-e.vStart,T=Math.max(1,e.vEnd-e.vStart),R=geSorted(e),top=R[0]&&R[0].v||0,sec=R[1]&&R[1].v||0,comp=top?1+.5*(1-(top-sec)/top):1;
 const P=geLive(e).map(get),pop=P.length?avg(P.map(m=>m.pop)):30,bz=P.length?avg(P.map(m=>m.buzz)):20,fanF=Math.max(.6,Math.min(2,Math.sqrt((S.fans||1)/(e.fans0||1))));
 const promo=1+((S.cal||[]).some(c=>c.rid==x.rid&&(c.type=='handshake'||c.type=='road'||c.type=='concert')&&evDays(c).some(d=>d==S.day||d==S.day-1))?.35:0)+((e.prelim||[]).some(p=>p.day==S.day-1)?.25:0)+(geIsWE(S.day)?.12:0);
 const dec=.024+.06*Math.exp(-t/9),fin=1+1.3*Math.pow(t/T,3),interest=(.8+pop/250)*(.85+bz/300)*(.9+Math.min(.4,P.length/80));
 return Math.max(0,Math.round(e.first*dec*fin*comp*fanF*promo*interest*Math.exp(geRandN()*.22)))}
function geCastDay(e,x){const t=S.day-e.vStart,T=Math.max(1,e.vEnd-e.vStart),pool=e.tokens-e.cast,fr=Math.min(.9,.32+.42*Math.pow(t/T,2)+(S.day==e.vEnd?.1:0));const V=Math.round(pool*fr);if(V>0){geAlloc(e,geWeights(e,x),V);e.cast+=V}return V}
function geSurgeDay(e){e.surge=e.surge||{};geLive(e).forEach(id=>{const s=e.surge[id];if(s&&s.until>=S.day)return;if(Math.random()<.025){const f=1.35+Math.random()*.5,len=rnd(3,7);e.surge[id]={from:S.day,until:S.day+len,f:+f.toFixed(2)};const m=get(id);e.news=e.news||[];e.news.push({day:S.day,id,txt:`${m.name} is trending — her fans are rallying votes.`});if(e.news.length>30)e.news.shift()}})}
function gePrelim(e,label){const R=geSorted(e),cap=geTotal(e),prev=(e.prelim||[]).at(-1);const rows=R.map((r,i)=>({id:r.id,v:r.v,rank:i<cap&&r.v>0?i+1:null}));
 const p={n:(e.prelim||[]).length+1,day:S.day,label,cast:e.cast,tokens:e.tokens,rows};e.prelim=e.prelim||[];e.prelim.push(p);
 if(prev){const P0=new Map(prev.rows.map(r=>[r.id,r.rank]));p.inn=rows.filter(r=>r.rank&&!P0.get(r.id)).map(r=>r.id);p.out=rows.filter(r=>!r.rank&&P0.get(r.id)).map(r=>r.id)}
 geN(`<li>📊 <b>${esc(e.name)}</b> — ${esc(label)} announced. 1st: <b>${esc((get(rows[0]&&rows[0].id)||{}).name||'—')}</b>. Rankings can still change until voting closes on ${longDate(e.vEnd)}.</li>`);return p}
function geStartVoting(e,x){if(e.st!='producing')return;e.parts=e.parts.filter(id=>{const m=get(id);return m&&m.status!='graduated'});e.rid=x.rid;e.title=x.title;e.vStart=S.day;e.vEnd=geEnd(S.day);e.st='voting';e.votes={};e.last={};e.ts=0;e.tokens=0;e.cast=0;e.daily=[];e.prelim=[];e.wd=[];e.fans0=Math.max(1,S.fans);e.first=Math.max(100,x.cd.units);
 e.heat={};e.parts.forEach(id=>e.heat[id]=+Math.exp(geRandN()*.18).toFixed(3));e.lockedGroups=JSON.parse(JSON.stringify(e.groups));x.ge=e.id;
 e.tokens+=x.cd.units;e.salesDay=S.day;const v=geCastDay(e,x);e.daily.push({day:S.day,sales:x.cd.units,cum:x.cd.units,tok:e.tokens,votes:v});gePrelim(e,'Preliminary Results (Release Day)');
 S.cal=S.cal||[];S.cal.push({id:'e'+(++S.sid),type:'gevote',ge:e.id,title:`${e.name} — voting closes`,day:e.vEnd,members:[],done:false})}
function geDay(e){const x=geSingleOf(e);if(!x||e.st!='voting')return;while(e.salesDay<Math.min(S.day,e.vEnd)){e.salesDay++;const d0=S.day;
  geSurgeDay(e);const u=geDemand(e,x);x.sales=(x.sales||0)+u;x.cd.units+=u;x.cd.orders=(x.cd.orders||0)+Math.round(u/1.05);const rev=u*300;x.rev=(x.rev||0)+rev;if(rev)earn(rev,`Election CD sales: ${x.title}`);e.tokens+=u;const v=geCastDay(e,x);e.daily.push({day:e.salesDay,sales:u,cum:x.cd.units,tok:e.tokens,votes:v});void d0;
  const t=e.salesDay-e.vStart;if(t>0&&t%14==0&&e.vEnd-e.salesDay>=7)gePrelim(e,`Preliminary Results — Update ${Math.round(t/14)+1}`)}
 if(e.salesDay>=e.vEnd)geClose(e)}
function geSig(rows){let h=2166136261;const s=JSON.stringify(rows.map(r=>[r.id,r.rank,r.votes]));for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619)>>>0;return h.toString(36)}
function geSnap(m){return{id:m.id,name:m.name,hue:m.hue,ap:JSON.parse(JSON.stringify(ap(m)))}}
function geClose(e){if(e.final||e.st!='voting')return;const R=geSorted(e),cap=geTotal(e),Rg=geRanges(e),last=(e.prelim||[]).at(-1),PL=new Map(last?last.rows.map(r=>[r.id,r.rank]):[]),prevE=gePrevDone(e);
 const prevR=new Map(prevE?prevE.final.rows.map(r=>[r.id,r.rank]):[]);e.expired=e.tokens-e.cast;
 const rows=R.map((r,i)=>{const m=get(r.id),rank=i<cap&&r.v>0?i+1:null,gi=rank?Rg.findIndex(([a,b])=>rank>=a&&rank<=b):-1;return{id:r.id,rank,votes:r.v,gi,gname:gi>=0?e.groups[gi].name:'Unranked',center:gi>=0&&rank==Rg[gi][0],top:rank&&rank<=3?rank:0,name:m.name,stage:m.stage||m.name,team:isAct(m)&&teamOf(m)?teamOf(m).name:TL(),trainee:m.status=='trainee',gen:m.gen||1,prelim:PL.get(r.id)??null,prev:prevE?(prevR.has(r.id)?prevR.get(r.id):'out'):null}});
 (e.wd||[]).forEach(id=>{const m=get(id)||(S.alumni||[]).find(a=>a.id==id);rows.push({id,rank:null,votes:e.votes[id]||0,gi:-1,gname:'Withdrawn',withdrawn:1,name:m?m.name:'#'+id,stage:m?(m.stage||m.name):'',team:'',gen:m?m.gen||1:1,prelim:null,prev:null})});
 e.final={day:S.day,rows,sig:geSig(rows),sales:(geSingleOf(e)||{cd:{units:0}}).cd.units,tokens:e.tokens,cast:e.cast,expired:e.expired};e.snap={};rows.forEach(r=>{const m=get(r.id);if(m)e.snap[r.id]=geSnap(m)});
 e.st='closed';(S.cal||[]).forEach(c=>{if(c.type=='gevote'&&c.ge==e.id)c.done=true});
 geN(`<li>🗳 <b>${esc(e.name)}</b> — voting has closed. ${e.cast.toLocaleString()} votes were cast; ${e.expired.toLocaleString()} unused tokens expired. The final results are sealed until the announcement ceremony — schedule it on a weekend in General Election.</li>`);toast(`${e.name}: voting closed. Schedule the ceremony.`)}
const gePrevDone=e=>geS().list.filter(z=>z!==e&&z.final&&z.st=='done'&&(z.vEnd||0)<(e.vStart??1e9)).sort((a,b)=>b.vEnd-a.vEnd)[0]||null;
// graduating during voting withdraws a participant (her votes stay cast; she is not ranked)
const _geGradHook=()=>{const e=geActive();if(e&&e.st=='voting'){e.wd=e.wd||[];e.parts.forEach(id=>{const m=get(id);if((!m||m.status=='graduated')&&!e.wd.includes(id))e.wd.push(id)})}};

// ---- ceremony scheduling ------------------------------------------------------------------------
function geDates(e){const L=[];for(let d=e.vEnd+1;d<=e.vEnd+70;d++)if(geIsWE(d)&&d>S.day)L.push(d);return L}
function geBook(){const e=geActive();if(!e||e.st!='closed')return toast('The ceremony can be scheduled only after voting closes.','err');const d=+ui.gecd,v=GE_VEN.find(z=>z.id==ui.gecv);
 if(!(d>e.vEnd))return toast('Choose a date after the voting close.','err');if(!geIsWE(d))return toast('The ceremony must be on a Saturday or Sunday.','err');if(d<=S.day)return toast('Choose a future date.','err');if(!v)return toast('Choose a venue.','err');
 if(!spend(v.cost,`${e.name}: ceremony venue (${v.n})`))return;e.cer={day:d,ven:v.id,vn:v.n,cap:v.cap,cost:v.cost,booked:S.day};e.st='scheduled';S.cal.push({id:'e'+(++S.sid),type:'ge',ge:e.id,title:`${e.name} — Ranking Announcement Ceremony (${v.n})`,day:d,members:[],done:false});toast(`Ceremony booked: ${longDate(d)} at ${v.n}.`);render()}
function geCerDay(e){if(e.st!='scheduled'||S.day<e.cer.day)return;e.st='ceremony';e.cp=e.cp||{i:0,rv:0};(S.cal||[]).forEach(c=>{if(c.type=='ge'&&c.ge==e.id)c.done=true});
 if(!e.cer.paid){const fill=Math.min(1,.55+Math.sqrt(S.fans/Math.max(1,e.cer.cap*8))*.45),att=Math.round(e.cer.cap*fill),rev=att*GE_EV.price,fans=Math.round(att*.05);earn(rev,`${e.name}: ceremony tickets`);S.fans+=fans;e.cer.paid={att,rev,fans}}
 geN(`<li>👑 <b>${esc(e.name)}</b> — today is the Ranking Announcement Ceremony at ${esc(e.cer.vn)} (${e.cer.paid.att.toLocaleString()} fans). Open <b>General Election</b> to begin.</li>`)}
const _geTick=tick;tick=function(){const r=_geTick.apply(this,arguments);try{_geGradHook();const e=geActive();if(e){if(e.st=='voting')geDay(e);geCerDay(e)}}catch(x){console.error(x)}return r};

// ---- GE single: production hooks ----------------------------------------------------------------
