const _geStart=startSingle;startSingle=function(){const p=S.pj,was=p&&p.status;const r=_geStart.apply(this,arguments);try{if(p&&p.ge&&was=='draft'&&p.status=='producing'){const e=geGet(p.ge);if(e&&e.st=='setup'){e.st='producing';e.pid=p.id;e.title=p.title.trim()}}}catch(x){console.error(x)}return r};
