const _geProf=profHtml;profHtml=function(m,cand){let h=_geProf.apply(this,arguments);if(cand||!m||!(m.geRec||[]).length)return h;const tab=ui.ptab||'stats';if(tab!='stats'&&tab!='disc')return h;
 const L=m.geRec.slice().sort((a,b)=>(a.ed||0)-(b.ed||0));return h+`<div class="c gerec"><h3>General Elections</h3><ul class="wll">${L.map(x=>`<li><b>${esc(x.name)}</b> <span class="wlpos ${x.top?'center':x.rank?'front':'none'}">${x.rank?geRn(x.rank):'Unranked'}</span> <span class="st">${esc(x.group||'')} · ${(x.votes||0).toLocaleString()} votes${x.change!=null?` · ${x.change>0?'▲'+x.change:x.change<0?'▼'+(-x.change):'＝'} vs previous`:''}${x.top?' · '+GE_CAPE[x.top].n:''}</span><br><span class="st">${WL.mood[x.mood]?WL.mood[x.mood][0]:''} ${esc(x.mood||'')} · Mental ${x.dmh>0?'+':''}${x.dmh} · Passion ${x.dpas>0?'+':''}${x.dpas}${x.dloy?' · Loyalty '+(x.dloy>0?'+':'')+x.dloy:''}</span>${x.speech?`<br><q>${esc(x.speech)}</q>`:''}</li>`).join('')}</ul></div>`};

