const _geRender=render;render=function(){try{if(S&&ui.geN&&ui.geN.length&&!ui.mod&&!ui.t&&!ui.gec){ui.mod={t:'html',h:`<h2 class="ht">General Election</h2><ul class="ms wln">${ui.geN.join('')}</ul>`};ui.geN=[]}}catch(x){console.error(x)}const r=_geRender.apply(this,arguments);
 try{const old=document.getElementById('gecerw');const e=S&&!ui.t&&ui.gec&&geGet(ui.gec);if(e&&e.st=='ceremony'){const a=document.getElementById('app'),d=old||document.createElement('div');d.id='gecerw';d.innerHTML=geCerHtml(e);if(!old&&a)a.appendChild(d);document.body.classList.add('gecer-on')}else{if(old)old.remove();document.body.classList.remove('gecer-on')}}catch(x){console.error(x)}return r};
function geMigrate(){const G=geS();G.list.forEach(e=>{e.groups=Array.isArray(e.groups)&&e.groups.length?e.groups:[{name:'Senbatsu',size:16}];e.parts=Array.isArray(e.parts)?e.parts:[];
  if(e.lockedGroups&&e.st!='setup'&&e.st!='producing')e.groups=JSON.parse(JSON.stringify(e.lockedGroups)); // structure stays exactly as locked
  if(e.final){const s=geSig(e.final.rows);e.final.ok=s==e.final.sig;if(!e.final.ok)console.warn('General Election record changed outside the game:',e.id)}
  if(e.st=='ceremony')e.cp=e.cp&&Number.isInteger(e.cp.i)?e.cp:{i:0,rv:0};
  if(e.st=='voting'){e.votes=e.votes||{};e.last=e.last||{};e.daily=e.daily||[];e.prelim=e.prelim||[];if(!e.cast)e.cast=0;if(e.cast>e.tokens)e.cast=e.tokens}});
 if(G.cur&&!geGet(G.cur))G.cur=null;try{geApplyNext()}catch(x){}}
const _geMig=migrate;migrate=function(){const r=_geMig.apply(this,arguments);try{geMigrate();ui.gec=null;ui.geN=[]}catch(x){console.error(x)}return r};
